\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Color Palette (data-forward, public exhibition) ──
\definecolor{primary}{HTML}{1E293B}     % deep slate
\definecolor{secondary}{HTML}{D97706}    % warm amber
\definecolor{accent}{HTML}{DC6B4A}      % coral
\definecolor{bgposter}{HTML}{0F172A}    % deep navy
\definecolor{redbg}{HTML}{1E293B}        % card backgrounds (tinted)
\definecolor{bluebg}{HTML}{1E293B}
\definecolor{darkbg}{HTML}{1E293B}
\definecolor{redtitlebg}{HTML}{2D3748}
\definecolor{bluetitlebg}{HTML}{2D3748}
\definecolor{darktitlebg}{HTML}{2D3748}
\definecolor{textlight}{HTML}{F8FAFC}
\definecolor{textmuted}{HTML}{94A3B8}
\definecolor{stathighlight}{HTML}{1E3A5F}
\definecolor{positive}{HTML}{10B981}    % green for progress
\definecolor{warning}{HTML}{F59E0B}      % amber for crisis

\pagecolor{bgposter}
\color{textlight}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=4pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}\textbullet}}
\setlist[enumerate]{leftmargin=20pt, itemsep=4pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{22}{28}\selectfont\color{textmuted}\textit{#3}}\vspace{2mm}%
}

% ── Card styles (left accent stripe) ──
\tcbset{
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=redtitlebg,
    toptitle=4pt, bottomtitle=4pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.25,color=black},
  },
  coralcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=bluetitlebg,
    toptitle=4pt, bottomtitle=4pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.25,color=black},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{textlight},
    coltitle=textlight, colbacktitle=darktitlebg,
    toptitle=4pt, bottomtitle=4pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.25,color=black},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=secondary!20!bgposter,
    borderline west={6pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=stathighlight,
    toptitle=4pt, bottomtitle=4pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.25,color=black},
  },
  bigstat/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=stathighlight,
    halign=center, valign=middle,
    left=10pt, right=10pt, top=8pt, bottom=8pt,
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=textlight,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.35}
]{name=title, column=1, span=2, between=top and row4}{
  {\fontsize{72}{86}\selectfont\bfseries\color{textlight} THE STATE OF GLOBAL EDUCATION}\\[10pt]
  {\fontsize{28}{34}\selectfont\color{secondary} Progress, Gaps, and Inequality}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=primary!8!bgposter, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=4pt, bottom=4pt,
  halign=center, valign=center,
  borderline south={2pt}{0pt}{secondary!40},
]{name=stats, column=1, span=2, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.22\linewidth}\centering
    \fcolorbox{secondary!50}{stathighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{52}{62}\selectfont\bfseries\color{secondary}\textless{} 1 in 5}\\[2pt]
      {\fontsize{20}{24}\selectfont\color{textmuted} Adults educated (1800)}\vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.22\linewidth}\centering
    \fcolorbox{positive!50}{stathighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{52}{62}\selectfont\bfseries\color{positive}\textgreater{} 4 in 5}\\[2pt]
      {\fontsize{20}{24}\selectfont\color{textmuted} Adults educated (today)}\vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.22\linewidth}\centering
    \fcolorbox{accent!50}{stathighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{52}{62}\selectfont\bfseries\color{accent} 244M}\\[2pt]
      {\fontsize{20}{24}\selectfont\color{textmuted} Children out of school}\vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.22\linewidth}\centering
    \fcolorbox{warning!50}{stathighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{52}{62}\selectfont\bfseries\color{warning}\textless{} 20\%}\\[2pt]
      {\fontsize{20}{24}\selectfont\color{textmuted} Reading proficiency (low-income)}\vspace{4pt}%
    }}
  \end{minipage}
}

% ══ LEFT COLUMN: TWO CENTURIES OF PROGRESS ══
\posterbox[ambercard, title={Two Centuries of Progress}]
{name=historical, column=1, between=row6 and row10}{
  \fontsize{30}{38}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item Early 1800s: Education was a luxury for the elite
    \item Fewer than 1 in 5 adults had any formal schooling
    \item Two centuries later: 4 in 5 adults are educated
    \item Literacy rates followed a similar trajectory
  \end{itemize}
  \vspace{6pt}
  \colorbox{positive!25}{\parbox{0.92\linewidth}{%
    \centering%
    {\fontsize{26}{32}\selectfont\color{positive}\bfseries Humanity has reversed the education gap}%
  }}
}

% ══ RIGHT COLUMN: THE LEARNING CRISIS ══
\posterbox[coralcard, title={The Learning Crisis: Enrollment $\neq$ Learning}]
{name=learning, column=2, between=row6 and row10}{
  \fontsize{30}{38}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item Enrollment numbers hide a hidden crisis
    \item In low-income countries, \textbf{\textless{}20\%} achieve minimum reading proficiency
    \item Children cannot identify key ideas in a text
    \item Being in school does not guarantee learning
  \end{itemize}
  \vspace{6pt}
  \colorbox{accent!25}{\parbox{0.92\linewidth}{%
    \centering%
    {\fontsize{26}{32}\selectfont\color{accent}\bfseries 244 Million Children Out of School}%
  }}
}

% ══ LEFT COLUMN: 244 MILLION OUT OF SCHOOL ══
\posterbox[highlightcard, title={244 Million Children Still Out of School}]
{name=outofschool, column=1, between=row10 and row15}{
  \fontsize{30}{38}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item \textbf{\textasctilde{}60 million} primary-age children out of school
    \item \textbf{\textasctilde{}184 million} secondary-age adolescents out of school
    \item Secondary-level dropout is a major driver
    \item Many complete primary but do not continue
  \end{itemize}
  \vspace{6pt}
  \colorbox{accent!30}{\parbox{0.92\linewidth}{%
    \centering%
    {\fontsize{42}{50}\selectfont\bfseries\color{accent} 244M}\\[4pt]
    {\fontsize{22}{26}\selectfont\color{textmuted} Children not enrolled (2023)}%
  }}
}

% ══ RIGHT COLUMN: QUALITY SCHOOLING — A WORLD DIVIDED ══
\posterbox[darkcard, title={Quality Schooling: A World Divided}]
{name=quality, column=2, between=row10 and row17}{
  \fontsize{30}{38}\selectfont
  \begin{itemize}[itemsep=6pt]
    \item \textbf{Learning-adjusted years of schooling} combine quantity and quality
  \end{itemize}
  \vspace{8pt}
  \colorbox{warning!25}{\parbox{0.92\linewidth}{%
    \centering%
    {\fontsize{60}{72}\selectfont\bfseries\color{warning}\textless{} 3 yrs}\\[4pt]
    {\fontsize{22}{26}\selectfont\color{textmuted} Poorest countries (Sub-Saharan Africa)}%
  }}
  \vspace{8pt}
  \colorbox{positive!25}{\parbox{0.92\linewidth}{%
    \centering%
    {\fontsize{60}{72}\selectfont\bfseries\color{positive}10+ yrs}\\[4pt]
    {\fontsize{22}{26}\selectfont\color{textmuted} High-income countries}%
  }}
  \vspace{8pt}
  \fontsize{26}{32}\selectfont\color{textmuted}
  South Asia \& Sub-Saharan Africa average: \textbf{\textless{}7 years}
}

% ══ LEFT COLUMN: GENDER GAP ══
\posterbox[ambercard, title={Closing the Gender Gap}]
{name=gender, column=1, between=row15 and row18}{
  \fontsize{28}{36}\selectfont
  \begin{itemize}[itemsep=6pt]
    \item Primary gap: Nearly closed globally
    \item Secondary gap: Nearly closed globally
    \item Tertiary: Women now exceed men in enrollment
    \item Exception: Girls in Afghanistan remain far less likely to attend
  \end{itemize}
}

% ══ LEFT COLUMN: KEY TAKEAWAY ══
\posterbox[highlightcard, title={The Path Forward}]
{name=takeaway, column=1, between=row18 and bottom}{
  \fontsize{28}{36}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item Progress is real but incomplete
    \item Close the gap between enrollment and actual learning
    \item Bridge the quality divide between rich and poor nations
  \end{itemize}
}

% ══ RIGHT COLUMN: BOTTOM CONTRAST VISUAL ══
\posterbox[darkcard, title={The Contrast at a Glance}]
{name=contrast, column=2, between=row17 and bottom}{
  \fontsize{28}{36}\selectfont
  \vspace{6pt}
  \colorbox{bgposter!5!primary}{\parbox{0.92\linewidth}{%
    \begin{tabular}{p{0.42\linewidth}|p{0.42\linewidth}}
      \rowcolor{warning!30}
      \fontsize{24}{30}\selectfont\color{textlight}\centering Poorest Countries &
      \fontsize{24}{30}\selectfont\color{textlight}\centering Rich Countries \\[8pt]
      \rowcolor{bgposter}
      \fontsize{48}{58}\selectfont\color{warning}\centering\textbf{\textless{}3} &
      \fontsize{48}{58}\selectfont\color{positive}\centering\textbf{10+} \\[8pt]
      \rowcolor{bgposter}
      \fontsize{20}{24}\selectfont\color{textmuted}\centering years of quality schooling &
      \fontsize{20}{24}\selectfont\color{textmuted}\centering years of quality schooling \\[8pt]
      \rowcolor{bgposter}
      \fontsize{18}{22}\selectfont\color{textmuted}\centering Sub-Saharan Africa &
      \fontsize{18}{22}\selectfont\color{textmuted}\centering High-income nations \\[8pt]
    \end{tabular}
  }}
}

\end{tcbposter}
\end{document}

